/// CB123 - SalesOrderExtractScreenforCSD
/// <summary>
/// Extension of sales picking report
/// </summary>
[ExtensionOf(classStr(WmsPickingList_OrderPickDP))]
internal final class METWmsPickingList_OrderPickDP_Extension
{
}

Method.Source:
    /// <summary>
    /// Initializes an instance of the <c>WMSPickingList_OrderPickTmp</c> with the context data.
    /// </summary>
    /// <param name = "_pickingListOrderPickTmp">A temporary order pick record.</param>
    /// <param name = "_orderTrans">An inventory order transaction.</param>
    protected void initPickingListOrderPickTmp(WMSPickingList_OrderPickTmp _pickingListOrderPickTmp, WMSOrderTrans _orderTrans)
    {
        next initPickingListOrderPickTmp(_pickingListOrderPickTmp, _orderTrans);

        if (_pickingListOrderPickTmp.TransRefId)
        {
            _pickingListOrderPickTmp.METWaveId = METWaveLine::findByDocumentNumber(wmsPickingRoute.TransRefId).WaveId;

            if (_pickingListOrderPickTmp.TransType == InventTransType::Sales)
            {
                SalesTable salesTable = SalesTable::find(_pickingListOrderPickTmp.TransRefId);
                METSalesTable metSalesTable = METSalesTable::findBySalesId(_pickingListOrderPickTmp.TransRefId);
                SalesLine salesLine = SalesLine::findInventTransId(_orderTrans.inventTransId);

                _pickingListOrderPickTmp.METOrderSplitGroup = metSalesTable.OrderSplitGroup;
                _pickingListOrderPickTmp.METCustAccount = salesTable.CustAccount;
                _pickingListOrderPickTmp.METSiteId = salesTable.InventSiteId;
                _pickingListOrderPickTmp.METWarehouse = salesTable.InventLocationId;
                _pickingListOrderPickTmp.METDeliveryInstructions = metSalesTable.DeliveryInstructions;
                _pickingListOrderPickTmp.METCustNameAndAddress = salesTable.DeliveryName + '\n' + salesTable.deliveryAddress().Address;
                _pickingListOrderPickTmp.METRoute = salesTable.METRoute;
                _pickingListOrderPickTmp.METRouteStopNum = salesTable.METRouteStopNum;
                _pickingListOrderPickTmp.METShippingDateConfirmed = salesTable.ShippingDateConfirmed;
                _pickingListOrderPickTmp.METLineNum = salesLine.LineNum;

                METSalesLine metSalesLineLoc;
                SalesLine salesLineLoc;

                select firstonly RecId from metSalesLineLoc
                exists join salesLineLoc
                    where salesLineLoc.Recid == metSalesLineLoc.salesLine
                    && salesLineLoc.SalesId == salesTable.SalesId
                    && metSalesLineLoc.SubstituteOriginalItemID != METConstants::emptyString;

                _pickingListOrderPickTmp.METAllowSubstitutions = metSalesLineLoc.RecId ? true : false;
                _pickingListOrderPickTmp.BarCode = salesLine.BarCode;

                if (_pickingListOrderPickTmp.ItemId)
                {
                    InventDim inventDimLoc = InventDim::find(wmsOrderTrans.InventDimId);
                    InventDim InventDimPickList;
                    MetReqItemTable metReqItemTable;
                    ReqItemTable reqItemTable;

                    select firstonly SlotLoc1Area, SlotLoc2Area from metReqItemTable
                    exists join reqItemTable
                        where reqItemTable.RecId == metReqItemTable.RefRecId
                        && reqItemTable.ItemId == _pickingListOrderPickTmp.ItemId
                    exists join InventDimPickList
                        where InventDimPickList.inventDimId == reqItemTable.CovInventDimId
                        && InventDimPickList.InventSiteId == inventDimLoc.InventSiteId
                        && InventDimPickList.InventLocationId == inventDimLoc.InventLocationId;

                     _pickingListOrderPickTmp.METSlotLoc1Area = metReqItemTable.SlotLoc1Area;
                     _pickingListOrderPickTmp.METSlotLoc2Area = metReqItemTable.SlotLoc2Area;

                     METCustParameters metCustParameters = METCustParameters::Find();

                    _pickingListOrderPickTmp.METGroup1Code = metCustParameters.ChilledWarehouseCategory;
                    _pickingListOrderPickTmp.METGroup2Code = metCustParameters.FrozenWarehouseCategory;

                    WHSFilters whsFilters;

                    select firstonly Description from whsFilters
                        where whsFilters.FilterNum == _pickingListOrderPickTmp.METGroup1Code;

                    _pickingListOrderPickTmp.METGroup1Description = whsFilters.Description;

                    whsFilters.clear();

                    select firstonly Description from whsFilters
                        where whsFilters.FilterNum == _pickingListOrderPickTmp.METGroup2Code;

                    _pickingListOrderPickTmp.METGroup2Description = whsFilters.Description;

                    _pickingListOrderPickTmp.METFilterCode = METInventItemOrderSetup::findByItemAndSite(_pickingListOrderPickTmp.ItemId, inventDimLoc.InventSiteId).FilterCode;
                }
            }
        }
        
    }
